-/**
- * Convert one hexadecimal character to its numeric value.
- */
-static int vessel_hex_value(char value)
-{
-  if (value >= '0' && value <= '9')
-  {
-    return value - '0';
-  }
-  if (value >= 'a' && value <= 'f')
-  {
-    return value - 'a' + 10;
-  }
-  if (value >= 'A' && value <= 'F')
-  {
-    return value - 'A' + 10;
-  }
-  return -1;
-}
