-static bool vessel_hex_decode(char *dest, size_t dest_size, const char *source)
-{
-  size_t length;
-  size_t bytes;
-  size_t i;
-  int high;
-  int low;
-
-  if (dest == NULL || dest_size == 0 || source == NULL)
-  {
-    return FALSE;
-  }
-  if (!strcmp(source, "-"))
-  {
-    dest[0] = '\0';
-    return TRUE;
-  }
-
-  length = strlen(source);
-  if ((length % 2) != 0)
-  {
-    dest[0] = '\0';
-    return FALSE;
-  }
-  bytes = length / 2;
-  if (bytes >= dest_size)
-  {
-    bytes = dest_size - 1;
-  }
-
-  for (i = 0; i < bytes; i++)
-  {
-    high = vessel_hex_value(source[i * 2]);
-    low = vessel_hex_value(source[i * 2 + 1]);
-    if (high < 0 || low < 0)
